  const availableLines=()=>{const status=Portal.CustomerPhone?.status||{};return (status.numbers||[]).filter(line=>line.status==='active'&&(line.branch_id||'default')===(status.branch_id||'default')&&(!line.assigned_user_id||line.assigned_user_id===ui.user()));};
