  async function pickTextContact(ticket){const target=extra.querySelector('[data-text-results]');if(!target)return;target.innerHTML=`<label class="fm-phone-search"><span>${icon('magnifying-glass')}</span><input type="search" aria-label="Find a contact to text" placeholder="Search contacts" autocomplete="off"></label><div class="fm-phone-text-pick" data-text-contacts role="status">Loading contacts…</div>`;const input=target.querySelector('input');const load=async query=>{try{const result=await request(`voice/contacts?query=${encodeURIComponent(query)}`);if(ticket!==sequence||input.value!==query)return;const contacts=result.contacts||[],list=target.querySelector('[data-text-contacts]');list.removeAttribute('role');list.innerHTML=contacts.map((c,i)=>`<button type="button" class="fm-phone-result" data-text-contact="${i}"><span class="fm-phone-person">${esc((c.name||'#')[0].toUpperCase())}</span><span>${esc(c.name)}<small>${esc(formatPhone(c.phone))}</small></span>${icon('chevron-right')}</button>`).join('')||emptyState('magnifying-glass','No matching contacts','');list.onclick=e=>{const button=e.target.closest('[data-text-contact]');if(button)void composeText(contacts[Number(button.dataset.textContact)]);};}catch(error){if(ticket===sequence)target.querySelector('[data-text-contacts]').textContent=error.message;}};input.oninput=()=>{clearTimeout(timer);const query=input.value;timer=setTimeout(()=>load(query),180);};void load('');input.focus();}
