        const controls=document.createElement('div');controls.hidden=true;controls.className='fm-phone-hidden-controls';body.querySelectorAll(':scope > .fmcm-form-grid').forEach(el=>controls.append(el));body.querySelectorAll(':scope > .fmcm-help:not([data-dev-destination])').forEach(el=>el.remove());
        const dialer=document.createElement('div');dialer.className='fm-phone-dialer';const content=document.createElement('div');content.className='fm-phone-dialer-content';content.append(number);const matches=document.createElement('div');matches.className='fm-phone-match';matches.setAttribute('aria-label','Matching contacts');content.append(matches,pad,start);dialer.append(content);body.append(dialer,controls);const dev=body.querySelector('[data-dev-destination]');if(dev)body.append(dev);
